import {getAction,getCharacter} from '@madou/catalog';
import {allCardInstanceIds,createGame,gameStats,transition,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand} from './scenario-tools.js';
export const mekaiPhysicalScenarios=['mekai-ordinary','mekai-dedicated','mekai-check-ordinary','mekai-check-dedicated'] as const;
export type MekaiPhysicalScenario=typeof mekaiPhysicalScenarios[number];
export function isMekaiPhysicalScenario(name:string):name is MekaiPhysicalScenario{return (mekaiPhysicalScenarios as readonly string[]).includes(name);}
export function makeMekaiPhysicalScenario(name:MekaiPhysicalScenario,players:{id:string;name:string}[],options:{level?:number;foreign?:boolean;defense?:'teleport'|'counter'|'ability'|'forbidden';fatal?:boolean}={}){
 let s=createGame(players,entropy(),{startingSeat:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];assignCharacter(s,a,options.foreign?'聖騎士ランスロット':'邪祭ウーノス');assignCharacter(s,b,options.defense==='counter'?'早駆けのランカスター':options.defense==='ability'?'小人のランバ':'侍大将のシン');assignCharacter(s,c,'大神官ジル');assignCharacter(s,d,'魔導王ガイナス');for(const p of Object.values(s.players))p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};const future=getCharacter(options.foreign?s.players[a]!.characterId:'c2-p07-r1c2')!;s.players[a]!.permanent!.magic_level=(options.level??(name.includes('-check-')?9:10))-future.base_stats.magic_level;s.players[a]!.permanent!.spirit=6-future.base_stats.spirit;s.players[b]!.permanent!.spirit=20+6-gameStats(s,b).spirit;if(options.fatal){s.players[a]!.permanent!.endurance=10-future.base_stats.endurance;s.players[b]!.permanent!.endurance=100+20-gameStats(s,b).endurance;}
 const card=takeCard(s,a,'a2-p13-r2c3'),ritual=options.foreign?null:takeCard(s,a,'a2-p05-r1c1'),own=[takeCard(s,a,'メタルゴーレム'),takeCard(s,a,'兵士')],target=[takeCard(s,b,'水竜'),takeCard(s,b,'砦')],fate=takeCard(s,c,'命運凶変'),defense=options.defense==='counter'?takeCard(s,b,'a2-p10-r3c3'):takeCard(s,b,'a2-p06-r1c1'),evade=options.defense==='forbidden'?takeCard(s,b,'a2-p05-r3c1'):null,maai=options.defense==='forbidden'?takeCard(s,b,'a2-p07-r1c1'):null;for(const id of [a,b,c,d])trimHand(s,id,card,...(ritual?[ritual]:[]),...own,...target,fate,defense,...(evade?[evade]:[]),...(maai?[maai]:[]));s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];
 function act(actorId:string,command:GameCommand){const input={actorId,command},e={...entropy(),dice:Array(100).fill(1)},r=transition(s,input,e);if(!r.ok)throw Error(`MEKAI_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('MEKAI_JSON');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('MEKAI_IDS');}
 for(const id of [a,b,c,d]){for(const guard of id===a?own:id===b?target:[])act(id,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:guard});act(id,{type:'PASS_SETUP'});}act(a,{type:'START_TURN'});act(a,{type:'CHOOSE_DRAW',draw:false});if(ritual){act(a,{type:'USE_REVIVAL_RITUAL'});for(let n=0;n<200;n++){const id=s.seatOrder[s.turnSeat]!,w=s.windows?.at(-1);if(w)act(w.participants[w.cursor]!,{type:'PASS'});else if(s.phase==='action'){if(id===a)break;act(id,{type:'PASS_ACTION'});}else if(s.phase==='withdrawal')act(id,{type:'PASS_WITHDRAWAL'});else if(s.phase==='hand-adjustment')act(id,{type:'END_TURN',discardIds:s.players[id]!.hand.filter(x=>x!==card).slice(0,Math.max(0,s.players[id]!.hand.length-gameStats(s,id).handLimit))});else if(s.phase==='turn-start')act(id,{type:'START_TURN'});else if(s.phase==='draw')act(id,{type:'CHOOSE_DRAW',draw:false});else throw Error('MEKAI_TURN');}if(s.players[a]!.characterId!=='c2-p07-r1c2')throw Error('MEKAI_RITUAL');}return s;
}
